<?php
require __DIR__ . '/config/config.php';
session_start();
if (empty($_SESSION['user_id'])) { header('Location: user/login.php'); exit; }
function checkoutItems(): array { $cart=$_SESSION['cart']??[];if(!$cart)return []; $ids=array_keys($cart);$marks=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT * FROM products WHERE id IN ($marks) AND is_active=1");$q->execute($ids);$items=[];foreach($q->fetchAll() as $p)$items[]=['product'=>$p,'qty'=>max(1,(int)($cart[$p['id']]['qty']??1))];return $items; }
$items=checkoutItems();if(!$items){header('Location: cart.php');exit;}$u=db()->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$u->execute([$_SESSION['user_id']]);$user=$u->fetch();$delivery=(float)setting('delivery_fee','50');$error='';$subtotal=0;foreach($items as $row)$subtotal+=(float)$row['product']['price']*$row['qty'];$total=$subtotal+$delivery;
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');if(!$name||!$phone||!$address)$error='নাম, ফোন ও ঠিকানা আবশ্যক।';foreach($items as $row)if($row['qty']>(int)$row['product']['stock'])$error='পর্যাপ্ত স্টক নেই।';if(!$error){$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO orders(user_id,customer_name,phone,email,address,total,status,payment_method,payment_status) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$_SESSION['user_id'],$name,$phone,$email,$address,$total,'pending','cod','unpaid']);$oid=$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$log=$pdo->prepare('INSERT INTO stock_logs(product_id,change_qty,reason,order_id) VALUES(?,?,?,?)');foreach($items as $row){$p=$row['product'];$qty=$row['qty'];$stock->execute([$qty,$p['id'],$qty]);if($stock->rowCount()!==1)throw new RuntimeException('stock');$item->execute([$oid,$p['id'],$p['name'],$qty,$p['price']]);$log->execute([$p['id'],-$qty,'Order placed',$oid]);}$pdo->commit();$_SESSION['cart']=[];header('Location: user/dashboard.php?success=1');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='অর্ডার তৈরি করা যায়নি।';}}}
?><!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout</title><link rel="stylesheet" href="assets/style.css"></head><body><header><div class="logo">G</div><strong><?=e(setting('site_name','GadgetMart'))?></strong><nav><a href="index.php">হোম</a><a href="cart.php">কার্ট</a></nav></header><main class="page-shell"><section class="panel-form"><h1>চেকআউট</h1><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post" class="stacked-form"><label>নাম<input name="name" value="<?=e($user['name']??'')?>" required></label><label>ফোন<input name="phone" value="<?=e($user['phone']??'')?>" required></label><label>ইমেইল<input name="email" type="email" value="<?=e($user['email']??'')?>"></label><label>ঠিকানা<textarea name="address" required><?=e($user['address']??'')?></textarea></label><div class="order-summary"><div class="summary-row"><span>পণ্যের মূল্য</span><span>৳<?=e(number_format($subtotal,2))?></span></div><div class="summary-row"><span>ডেলিভারি</span><span>৳<?=e(number_format($delivery,2))?></span></div><div class="summary-row total"><span>মোট</span><strong>৳<?=e(number_format($total,2))?></strong></div></div><button class="btn full-width">ক্যাশ অন ডেলিভারি অর্ডার করুন</button></form></section></main></body></html>
